<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import type { GrammarCurriculum } from '@/api/grammar'
import MarkdownRenderer from '@/components/MarkdownRenderer.vue'
import { applyPageMeta } from '@/lib/seo'
import { grammarCurriculumCache } from '@/lib/publicContentCache'

const data=ref<GrammarCurriculum|null>(null);const loading=ref(true);const failed=ref(false)
const steps=computed(()=>data.value?.course.roadmapMarkdown?.split('\n').map(s=>s.replace(/^\d+\.\s*/, '').trim()).filter(Boolean)??[])
onMounted(async()=>{try{data.value=await grammarCurriculumCache.load('grammar');applyPageMeta({title:data.value.course.title,description:data.value.course.summary||undefined})}catch{failed.value=true}finally{loading.value=false}})
</script>

<template>
  <section v-if="loading" class="grammar-state">课程加载中…</section><section v-else-if="failed||!data" class="grammar-state">语法课程暂未开放。</section>
  <section v-else class="grammar-home">
    <header class="grammar-hero"><div><p>ENGLISH GRAMMAR · SYSTEMATIC COURSE</p><h1>{{ data.course.title }}</h1><h2>{{ data.course.subtitle }}</h2><span>{{ data.course.summary }}</span><RouterLink v-if="data.sections[0]?.lessons[0]" :to="`/english/grammar/${data.sections[0].lessons[0].slug}`">从第一课开始 →</RouterLink></div><div class="grammar-hero__mark"><b>42</b><span>课节</span><small>10 CHAPTERS</small></div></header>
    <section class="grammar-intro"><div><p>COURSE PURPOSE</p><h2>建立能用于分析与表达的语法框架</h2></div><p>{{ data.course.introduction }}</p></section>
    <section class="roadmap"><header><p>LEARNING PATH</p><h2>九阶段学习路线</h2></header><ol><li v-for="(step,index) in steps" :key="step"><b>{{ String(index+1).padStart(2,'0') }}</b><span>{{ step }}</span></li></ol></section>
    <section class="curriculum"><header><div><p>CURRICULUM</p><h2>完整课程目录</h2></div><span>{{ data.sections.length }} 章 · {{ data.sections.reduce((n,s)=>n+s.lessonCount,0) }} 课</span></header><div class="curriculum__grid"><article v-for="(section,index) in data.sections" :key="section.id"><div class="curriculum__chapter"><b>{{ String(index+1).padStart(2,'0') }}</b><div><h3>{{ section.title }}</h3><p>{{ section.lessonCount }} 个课节</p></div></div><ol><li v-for="lesson in section.lessons" :key="lesson.id"><RouterLink :to="`/english/grammar/${lesson.slug}`"><span>{{ lesson.slug }}</span><strong>{{ lesson.title }}</strong><i>→</i></RouterLink></li></ol></article></div></section>
    <section v-if="data.course.roadmapMarkdown" class="source-roadmap"><MarkdownRenderer :source="data.course.roadmapMarkdown"/></section>
  </section>
</template>

<style scoped>
